class MathHelper {
    static int square(int n) { return n * n; }
    static boolean isPrime(int n) {
        if (n < 2) return false;
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) return false;
        }
        return true;
    }
}

public static void main(String[] args) {
    System.out.println("square(7) = " + MathHelper.square(7));
