class Version {
    int major, minor, patch;
    Version(int major, int minor, int patch) { this.major = major; this.minor = minor; this.patch = patch; }
    boolean isNewerThan(Version other) {
        if (major != other.major) return major > other.major;
        if (minor != other.minor) return minor > other.minor;
        return patch > other.patch;
    }
}

public static void main(String[] args) {
    Version v1 = new Version(1, 2, 3);
    Version v2 = new Version(1, 2, 4);
    Version v3 = new Version(2, 0, 0);
    Version v4 = new Version(1, 9, 9);
    System.out.println("1.2.4 nowsza od 1.2.3: " + v2.isNewerThan(v1));
    System.out.println("2.0.0 nowsza od 1.9.9: " + v3.isNewerThan(v4));
}

