        double suma = 0;
        for (double g : grades) suma += g;
        return suma / grades.length;
    }
    double max() {
        double m = grades[0];
        for (double g : grades) if (g > m) m = g;
        return m;
    }
    double min() {
        double m = grades[0];
        for (double g : grades) if (g < m) m = g;
        return m;
    }
}

public static void main(String[] args) {
