class Matrix2x2 {
    double[][] data;
    Matrix2x2(double a, double b, double c, double d) {
        data = new double[][]{{a, b}, {c, d}};
    }
    double determinant() {
        return data[0][0] * data[1][1] - data[0][1] * data[1][0];
    }
    Matrix2x2 multiply(Matrix2x2 other) {
        double a = data[0][0] * other.data[0][0] + data[0][1] * other.data[1][0];
        double b = data[0][0] * other.data[0][1] + data[0][1] * other.data[1][1];
        double c = data[1][0] * other.data[0][0] + data[1][1] * other.data[1][0];
        double d = data[1][0] * other.data[0][1] + data[1][1] * other.data[1][1];
        return new Matrix2x2(a, b, c, d);
    }
    void print() {
        System.out.println("[" + data[0][0] + ", " + data[0][1] + "]");
        System.out.println("[" + data[1][0] + ", " + data[1][1] + "]");
    }
}

public static void main(String[] args) {
    Matrix2x2 m = new Matrix2x2(1, 2, 3, 4);
    m.print();
    System.out.println("Wyznacznik: " + m.determinant());
