class DBConnection {
    boolean inUse = false;
    int id;
    DBConnection(int id) { this.id = id; }
}

class ConnectionPool {
    DBConnection[] pool = { new DBConnection(1), new DBConnection(2), new DBConnection(3) };
    DBConnection acquire() {
        for (DBConnection c : pool) {
            if (!c.inUse) { c.inUse = true; return c; }
        }
        return null;
    }
    void release(DBConnection c) { c.inUse = false; }
}

public static void main(String[] args) {
    ConnectionPool poolManager = new ConnectionPool();
    DBConnection c1 = poolManager.acquire();
    DBConnection c2 = poolManager.acquire();
    DBConnection c3 = poolManager.acquire();
    DBConnection c4 = poolManager.acquire();
    System.out.println("c1: " + c1.id + ", c2: " + c2.id + ", c3: " + c3.id + ", c4: " + c4);
    poolManager.release(c1);
    DBConnection c5 = poolManager.acquire();
    System.out.println("c5 (po zwolnieniu c1): " + c5.id);
}

