class ScientificCalculator {
    String[] history = new String[5];
    int index = 0;
    double oblicz(double a, String op, double b) {
        double result = switch (op) {
            case "+" -> a + b;
            case "-" -> a - b;
            case "*" -> a * b;
            case "/" -> a / b;
            case "^" -> Math.pow(a, b);
            case "%" -> a % b;
            default -> throw new IllegalArgumentException("Nieznany operator: " + op);
        };
        history[index % 5] = a + " " + op + " " + b + " = " + result;
        index++;
        return result;
    }
    void printHistory() {
        int count = Math.min(index, 5);
        for (int i = 0; i < count; i++) {
            System.out.println(history[i]);
        }
    }
    static long factorial(int n) {
        long result = 1;
        for (int i = 2; i <= n; i++) result *= i;
        return result;
    }
}

public static void main(String[] args) {
    ScientificCalculator calc = new ScientificCalculator();
    calc.oblicz(1, "+", 1);
    calc.oblicz(2, "-", 1);
    calc.oblicz(3, "*", 2);
    calc.oblicz(10, "/", 2);
    calc.oblicz(2, "^", 3);
    calc.oblicz(7, "%", 3);
    calc.oblicz(5, "+", 5);
    calc.printHistory();
    System.out.println("5! = " + ScientificCalculator.factorial(5));
}
